const premium={
  1:{audience:'Người mới bắt đầu hoặc chưa chắc nền tảng Pinyin',duration:'8 tuần · 3 buổi/tuần',focus:'Phát âm, 150 từ nền tảng và hội thoại đời sống',result:'Tự giới thiệu, hỏi đáp thông tin và giao tiếp câu ngắn'},
  2:{audience:'Người đã biết Pinyin và mẫu câu HSK 1',duration:'10 tuần · 3 buổi/tuần',focus:'Phản xạ giao tiếp trong 7 chủ đề quen thuộc',result:'Xử lý mua sắm, di chuyển, sức khỏe và công việc'},
  3:{audience:'Người muốn chuyển từ câu đơn sang diễn đạt theo chủ đề',duration:'12 tuần · 3 buổi/tuần',focus:'600 từ vựng, đọc hiểu và luyện đề có hướng dẫn',result:'Viết đoạn ngắn, nghe hội thoại dài và tự tin thi HSK 3'},
  4:{audience:'Người cần tiếng Trung cho học tập, du lịch hoặc công việc',duration:'16 tuần · 3 buổi/tuần',focus:'Câu phức, giao tiếp trung cấp và đọc hiểu thực tế',result:'Diễn đạt độc lập trong các tình huống quen thuộc'},
  5:{audience:'Người muốn nâng cao năng lực đọc – viết học thuật',duration:'20 tuần · 3 buổi/tuần',focus:'Từ vựng chuyên đề, lập luận và văn phong trang trọng',result:'Đọc báo, viết theo chủ đề và chuẩn bị HSK 5'},
  6:{audience:'Người học trình độ cao muốn làm chủ văn bản chuyên sâu',duration:'24 tuần · 3 buổi/tuần',focus:'Phân tích, tóm tắt và diễn đạt ý phức tạp',result:'Đọc hiểu văn bản dài và xây chiến thuật HSK 6'}
};
async function csrf(){if(!csrfToken)csrfToken=(await fetch('api.php?action=get_csrf_token')).json().then(x=>x.csrf_token);return csrfToken}
function esc(s){const e=document.createElement('span');e.textContent=s||'';return e.innerHTML}
function renderPremiumDetails(info,lessons){
  const meta=premium[course.hsk_level]||premium[1];
  const story=esc(course.description||course.short_description||info.subtitle).split(/\n+/).filter(Boolean).map(p=>`<p>${p}</p>`).join('');
  const outcomes=document.querySelector('.layout>div:first-child .section');
  if(outcomes)outcomes.insertAdjacentHTML('afterend',`<section class="section"><h2>Khóa học này dành cho ai?</h2><div class="course-story">${story}</div><div class="value-grid"><div class="value-card"><strong>Phù hợp với</strong><span>${esc(meta.audience)}</span></div><div class="value-card"><strong>Nhịp học gợi ý</strong><span>${esc(meta.duration)}</span></div><div class="value-card"><strong>Trọng tâm</strong><span>${esc(meta.focus)}</span></div></div></section><section class="section"><h2>Giá trị bạn nhận được</h2><div class="skill-grid"><div class="skill-card"><b>Học theo lộ trình rõ ràng</b><p>Mỗi bài dẫn từ từ vựng, mẫu câu đến thực hành; không phải tự ghép kiến thức rời rạc.</p></div><div class="skill-card"><b>Ôn tập trực tiếp trên web</b><p>Liên kết bài học, flashcard, luyện viết chữ Hán và bài tập để biến kiến thức thành phản xạ.</p></div><div class="skill-card"><b>Theo dõi tiến độ cá nhân</b><p>Đánh dấu phần đã hoàn thành để luôn biết bài tiếp theo cần học.</p></div><div class="skill-card"><b>Kết quả đầu ra cụ thể</b><p>${esc(meta.result)}</p></div></div></section>`);
  const curriculum=document.querySelector('.layout>div:first-child .section:last-child');
  if(curriculum)curriculum.innerHTML=`<h2>Chương trình học chi tiết</h2><p class="course-story">${lessons.length?`Toàn bộ ${lessons.length} bài học được sắp xếp tăng dần về độ khó. Mỗi bài có từ vựng trọng tâm, mẫu ngữ pháp và phần luyện tập.`:'Nội dung đang được hoàn thiện.'}</p><div class="module-list">${lessons.map((l,i)=>`<article class="module"><span class="module-index">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(l.title)}</h3><p>${esc(l.description||'Học từ vựng, cấu trúc câu và thực hành theo chủ đề.')}${l.grammar?`<br><b>Ngữ pháp trọng tâm:</b> ${esc(l.grammar)}`:''}</p></div><span class="module-tag">${l.vocab_count||10} từ mới</span></article>`).join('')}</div><div class="learning-plan"><div><b>1. Học hiểu</b><span>Từ vựng, ngữ cảnh và ví dụ chuẩn.</span></div><div><b>2. Luyện phản xạ</b><span>Viết chữ Hán và bài tập theo bài.</span></div><div><b>3. Củng cố</b><span>Ôn lại tiến độ và áp dụng vào tình huống.</span></div></div></section><section class="section faq"><h2>Cam kết trải nghiệm học</h2><details open><summary>Tôi có thể học theo tốc độ riêng không?</summary><p>Có. Nội dung được mở theo tài khoản sau khi đăng ký; bạn có thể quay lại bài cũ, ôn từ vựng và tiếp tục từ tiến độ của mình.</p></details><details><summary>Khóa học có những hình thức luyện tập nào?</summary><p>Mỗi lộ trình liên kết với từ vựng, flashcard, luyện viết chữ Hán và các bài thực hành sẵn có trên hệ thống.</p></details><details><summary>Sau khi hoàn thành tôi nên học gì tiếp?</summary><p>${course.hsk_level<6?'Bạn có thể chuyển lên HSK '+(Number(course.hsk_level)+1)+' theo lộ trình liền mạch.':'Bạn có thể dùng lộ trình này để tiếp tục luyện đọc sâu, tóm tắt và đề HSK 6.'}</p></details></section>`;
}
function render(){const info=content[course.hsk_level]||content[1];const lessons=(course.lessons||[]);document.getElementById('app').className='';document.getElementById('app').innerHTML=`
<header class="hero"><div><span class="level">KHÓA HỌC HSK ${course.hsk_level||''}</span><h1>${esc(course.title)}</h1><p>${esc(course.description||course.short_description||info.subtitle)}</p><div class="metrics"><span class="metric">📚 ${lessons.length||course.lesson_count||0} bài học</span><span class="metric">⏱ ${info.time}</span><span class="metric">🈶 ${info.words}</span><span class="metric">♾️ Học mọi lúc</span></div></div><div class="hero-mark">${info.icon}</div></header>
<div class="layout"><div><section class="section"><h2>Sau khóa học bạn có thể</h2><div class="outcomes">${info.out.map((x,i)=>`<div class="outcome"><b>✓ Mục tiêu ${i+1}</b>${x}</div>`).join('')}</div></section><section class="section"><h2>Nội dung khóa học</h2><ul class="curriculum">${lessons.length?lessons.map((l,i)=>`<li><span class="lesson-num">${i+1}</span><span class="lesson-title">${esc(l.title)}</span><span class="lesson-meta">${l.vocab_count||'10'} từ · 30 phút</span></li>`).join(''):'<li>Giáo trình đang được cập nhật.</li>'}</ul></section></div><aside><div class="buy-card"><h3>Đăng ký khóa học</h3><div class="price">Miễn phí</div>${course.enrolled?'<a class="btn btn--primary" href="learn_course.php?slug='+encodeURIComponent(course.slug)+'">Vào khu vực học</a>':'<button class="btn btn--primary" id="buy">Đăng ký học ngay</button>'}<p class="safe"><span>✓</span> Mở quyền học ngay sau khi đăng ký</p><div class="pay-panel" id="pay"></div></div></aside></div>`;if(!course.enrolled)document.getElementById('buy').onclick=createOrder}
async function createOrder(){let token=await csrf();let r=await fetch('api.php?action=create_order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({course_id:course.id,csrf_token:token})}).then(x=>x.json()).catch(()=>({success:false,message:'Không kết nối được máy chủ.'}));if(!r.success){alert(r.message||'Không thể đăng ký khóa học.');if((r.message||'').includes('đăng nhập'))location.href='login.php';return}if(r.order.status==='paid'){location.href='learn_course.php?slug='+encodeURIComponent(course.slug);return}}
fetch('api.php?action=get_course&slug='+encodeURIComponent(slug||'')).then(x=>x.json()).then(r=>{if(!r.success){document.getElementById('app').className='section';document.getElementById('app').textContent=r.message||'Không tìm thấy khóa học.';return}course=r.course;render()}).catch(()=>{document.getElementById('app').className='section';document.getElementById('app').textContent='Không thể tải khóa học. Hãy thử lại.'});
let premiumRendered=false;const premiumObserver=setInterval(()=>{if(!premiumRendered&&course&&document.querySelector('.layout>div:first-child .section')){renderPremiumDetails(content[course.hsk_level]||content[1],course.lessons||[]);premiumRendered=true;clearInterval(premiumObserver)}},50);
</script></body></html>
